#ifndef POINT_N_CLICK_CAMERA_DEADZONE
#define POINT_N_CLICK_CAMERA_DEADZONE 24
#endif

UBYTE last_hit_trigger;

static void pointnclick_init(void) {
    camera_offset_x = 0;
    camera_offset_y = 0;
    camera_deadzone_x = POINT_N_CLICK_CAMERA_DEADZONE;
    camera_deadzone_y = POINT_N_CLICK_CAMERA_DEADZONE;
    act_dir[0] = DIR_RIGHT;
    actor_set_anim(0u, ANIM_CURSOR);
}

static void pointnclick_update(void) {
    UBYTE angle;
    UBYTE hit_trigger;
    UBYTE is_hover_trigger;
    UBYTE is_hover_actor;
    unsigned char hit_actor;

    player_moving = FALSE;

    // Handle input
    if (INPUT_LEFT) {
        player_moving = TRUE;
        if (INPUT_UP) {
            angle = ANGLE_315DEG;
        } else if (INPUT_DOWN) {
            angle = ANGLE_225DEG;
        } else {
            angle = ANGLE_270DEG;
        }
    } else if (INPUT_RIGHT) {
        player_moving = TRUE;
        if (INPUT_UP) {
            angle = ANGLE_45DEG;
        } else if (INPUT_DOWN) {
            angle = ANGLE_135DEG;
        } else {
            angle = ANGLE_90DEG;
        }
    } else if (INPUT_UP) {
        player_moving = TRUE;
        angle = ANGLE_0DEG;
    } else if (INPUT_DOWN) {
        player_moving = TRUE;
        angle = ANGLE_180DEG;
    } else {
        angle = ANGLE_0DEG;
    }

    // Move cursor
    if (player_moving) {
        NGC_TRANSLATE_ANGLE(0u, angle, act_speed[0]);
        // Clamp X
        if (act_x[0] + act_bounds[0] > image_width_subpx) {
            act_x[0] = -act_bounds[0];
        } else if (act_x[0] + act_bounds[1] > image_width_subpx) {
            act_x[0] = image_width_subpx - EXCLUSIVE_OFFSET(act_bounds[1]);
        }
        // Clamp Y
        if (act_y[0] + act_bounds[2] > image_height_subpx) {
            act_y[0] = -act_bounds[2];
        } else if (act_y[0] + act_bounds[3] > image_height_subpx) {
            act_y[0] = image_height_subpx - EXCLUSIVE_OFFSET(act_bounds[3]);
        }
    }

    // Check for trigger collisions
    hit_trigger = NGC_TRIGGER_AT_PLAYER();

    // Check for actor collisions
    hit_actor = player_overlap();

    is_hover_trigger = (hit_trigger != NO_TRIGGER_COLLISON)
        && NGC_TRIGGER_HAS_SCRIPT(hit_trigger);

    is_hover_actor = (hit_actor != 255u) && NGC_ACTOR_HAS_SCRIPT(hit_actor);

    // Set cursor animation
    if (is_hover_trigger || is_hover_actor) {
        actor_set_anim(0u, ANIM_CURSOR_HOVER);
    } else {
        actor_set_anim(0u, ANIM_CURSOR);
    }

    if (INPUT_A_PRESSED) {
        player_moving = FALSE;
        if (is_hover_actor) {
            // Run actor script
            NGC_ACTOR_INTERACT(hit_actor);
        }
        else if (is_hover_trigger) {
            // Run trigger script
            NGC_TRIGGER_INTERACT(hit_trigger);
        }
    }
}
